mapper.select:
select id, child_no, child_name, age, gender, assess_type, remark, is_deleted, create_time, update_time from child_info WHERE is_deleted = 0
AND child_name LIKE CONCAT('%', #{childName}, '%')
AND child_no LIKE CONCAT('%', #{childNo}, '%')
AND assess_type = #{assessType}
ORDER BY ${sortField} ${sortOrder}
